// ============================================================================
// Native WPF-UI integration — compiled XAML (BAML) via the SDK-style project.
// Views/*.xaml now carry x:Class and are generated by the WPF markup compiler;
// no runtime XamlReader.Load and no loose XAML files are required.
// ============================================================================

using System;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Navigation;
using Wpf.Ui.Appearance;
using Wpf.Ui.Controls;

namespace ClearWin
{
    public partial class MainWindow
    {
        /// <summary>
        /// Apply the DWM-only Mica backdrop. WPF-UI 4.0.3 signature:
        /// Apply(ApplicationTheme, Wpf.Ui.Controls.WindowBackdropType, bool).
        /// </summary>
        private void ApplyNativeBackdrop()
        {
            try
            {
                ApplicationThemeManager.Apply(
                    ApplicationTheme.Dark,
                    WindowBackdropType.Mica,
                    true);
                CWLog.Info("UI.Native", "WPF-UI Mica backdrop applied (DWM hardware accelerated).");
            }
            catch (Exception ex)
            {
                CWLog.Error("UI.Native.Mica", ex);
            }
        }

        /// <summary>
        /// A Page may only be hosted by a Window or a Frame. Wrapping in a
        /// Frame avoids "Page can have only Window or Frame as parent".
        /// </summary>
        private UIElement HostCompiledPage(Page page)
        {
            return new Frame
            {
                Content = page,
                NavigationUIVisibility = NavigationUIVisibility.Hidden,
                HorizontalAlignment = HorizontalAlignment.Stretch,
                VerticalAlignment = VerticalAlignment.Stretch
            };
        }

        /// <summary>Dispose the WebView2 host so it releases RAM immediately.</summary>
        private void DisposeWebUi()
        {
            if (_webUiHost == null) return;
            try { _webUiHost.Dispose(); }
            catch (Exception ex) { CWLog.Error("UI.Native.WebUiDispose", ex); }
            _webUiHost = null;
        }

        /// <summary>Show the native (compiled) Game Boost page as the main workspace.</summary>
        private void ShowNativeGameBoost()
        {
            try
            {
                DisposeWebUi();
                var page = new Views.GameBoostPage
                {
                    DataContext = new ViewModels.GameBoostViewModel()
                };
                if (_mainContent == null)
                    _mainContent = new ContentControl { Margin = new Thickness(12) };
                _mainContent.Content = HostCompiledPage(page);
                _mainContent.Visibility = Visibility.Visible;
                CWLog.Info("UI.Native", "GameBoostPage loaded from compiled BAML with GameBoostViewModel.");
            }
            catch (Exception ex)
            {
                CWLog.Error("UI.Native.GameBoost", ex);
                ShowWebUiFallback("Native view could not be loaded: " + ex.Message);
            }
        }

        /// <summary>Show the native (compiled) Smart Agent settings page.</summary>
        private void ShowNativeAiSettings()
        {
            try
            {
                var page = new Views.AiSettingsPage
                {
                    DataContext = new ViewModels.GameBoostViewModel()
                };
                if (_mainContent != null) _mainContent.Content = HostCompiledPage(page);
            }
            catch (Exception ex) { CWLog.Error("UI.Native.AiSettings", ex); }
        }

        /// <summary>Show the native (compiled) Settings page.</summary>
        private void ShowNativeSettings()
        {
            try
            {
                var page = new Views.SettingsPage();
                if (_mainContent != null) _mainContent.Content = HostCompiledPage(page);
            }
            catch (Exception ex) { CWLog.Error("UI.Native.Settings", ex); }
        }
    }
}
